/**
 * Arithmetic in the finite field GF(2^8) used by Rijndael/AES.
 *
 * The field is F2[x] / (x^8 + x^4 + x^3 + x + 1), i.e. every byte is read as a
 * polynomial with coefficients in {0, 1} and the reduction polynomial is 0x11b.
 * Everything the cipher needs (the S-box, the MixColumns constants, the key
 * schedule round constants) is derived from the two primitives below, so no
 * magic tables have to be transcribed by hand.
 */

/** The AES reduction polynomial x^8 + x^4 + x^3 + x + 1. */
export const AES_POLYNOMIAL = 0x11b;

/**
 * Multiply two field elements (russian-peasant style, constant shape).
 *
 * @param {number} a byte operand
 * @param {number} b byte operand
 * @returns {number} the product, reduced modulo {@link AES_POLYNOMIAL}
 */
export function gmul(a, b) {
  let product = 0;
  let left = a & 0xff;
  let right = b & 0xff;

  while (right !== 0) {
    if (right & 1) product ^= left;
    right >>= 1;
    left <<= 1;
    if (left & 0x100) left ^= AES_POLYNOMIAL;
  }

  return product & 0xff;
}

/**
 * Multiplicative inverse in GF(2^8), with 0 mapped to 0 as Rijndael requires.
 *
 * The field has 255 non-zero elements, so a^254 == a^-1 for every a != 0.
 *
 * @param {number} a byte operand
 * @returns {number} the inverse of `a`
 */
export function ginv(a) {
  if ((a & 0xff) === 0) return 0;

  let result = 1;
  let base = a & 0xff;
  let exponent = 254;

  while (exponent !== 0) {
    if (exponent & 1) result = gmul(result, base);
    base = gmul(base, base);
    exponent >>= 1;
  }

  return result;
}

/**
 * Rotate a byte left, used by the S-box affine transformation.
 *
 * @param {number} value byte to rotate
 * @param {number} count number of positions
 * @returns {number} the rotated byte
 */
export function rotl8(value, count) {
  const v = value & 0xff;
  return ((v << count) | (v >> (8 - count))) & 0xff;
}

