/**
 * Lookup tables for AES, generated once at module load from the field
 * arithmetic in `galois.mjs` rather than being hard-coded.
 */

import { ginv, gmul, rotl8 } from './galois.mjs';

/**
 * The Rijndael substitution box: inversion in GF(2^8) followed by the affine
 * map s = b ^ rotl(b,1) ^ rotl(b,2) ^ rotl(b,3) ^ rotl(b,4) ^ 0x63.
 */
function buildSbox() {
  const sbox = new Uint8Array(256);

  for (let i = 0; i < 256; i++) {
    const b = ginv(i);
    sbox[i] = (b ^ rotl8(b, 1) ^ rotl8(b, 2) ^ rotl8(b, 3) ^ rotl8(b, 4) ^ 0x63) & 0xff;
  }

  return sbox;
}

/** Invert a permutation table. */
function invertTable(table) {
  const inverse = new Uint8Array(256);
  for (let i = 0; i < 256; i++) inverse[table[i]] = i;
  return inverse;
}

/** Precompute the byte-wise product with a fixed MixColumns coefficient. */
function buildMulTable(coefficient) {
  const table = new Uint8Array(256);
  for (let i = 0; i < 256; i++) table[i] = gmul(i, coefficient);
  return table;
}

/**
 * Round constants for the key schedule: rcon[i] = x^(i-1) in GF(2^8).
 *
 * Eleven entries cover the deepest schedule AES ever needs (AES-128 uses ten
 * round constants; the leading 0x01 keeps the array 1-indexed like the spec).
 */
function buildRcon(count) {
  const rcon = new Uint8Array(count);
  let value = 1;

  for (let i = 0; i < count; i++) {
    rcon[i] = value;
    value = gmul(value, 0x02);
  }

  return rcon;
}

export const SBOX = buildSbox();
export const INV_SBOX = invertTable(SBOX);
export const RCON = buildRcon(11);

// MixColumns multiplies by 2 and 3; InvMixColumns by 9, 11, 13 and 14.
export const MUL2 = buildMulTable(0x02);
export const MUL3 = buildMulTable(0x03);
export const MUL9 = buildMulTable(0x09);
export const MUL11 = buildMulTable(0x0b);
export const MUL13 = buildMulTable(0x0d);
export const MUL14 = buildMulTable(0x0e);

