/**
 * The AES key schedule (FIPS-197, section 5.2).
 */

import { RCON, SBOX } from './tables.mjs';

/** Key lengths AES accepts, in bytes. */
export const VALID_KEY_SIZES = [16, 24, 32];

/** Number of rounds for each supported key length, keyed by Nk (key words). */
function roundsForKeyWords(nk) {
  return nk + 6;
}

/**
 * Expand a cipher key into the flat round-key material used by the cipher.
 *
 * @param {Uint8Array} key 16, 24 or 32 raw key bytes
 * @returns {{ roundKeys: Uint8Array, rounds: number }} `roundKeys` holds
 *   `16 * (rounds + 1)` bytes, laid out one 16-byte round key after another.
 */
export function expandKey(key) {
  const nk = key.length / 4;
  const rounds = roundsForKeyWords(nk);
  const totalWords = 4 * (rounds + 1);
  const words = new Uint8Array(totalWords * 4);

  words.set(key);

  for (let i = nk; i < totalWords; i++) {
    const p = (i - 1) * 4;
    let t0 = words[p];
    let t1 = words[p + 1];
    let t2 = words[p + 2];
    let t3 = words[p + 3];

    if (i % nk === 0) {
      // RotWord, then SubWord, then xor in the round constant.
      const rotated = [t1, t2, t3, t0];
      t0 = SBOX[rotated[0]] ^ RCON[i / nk - 1];
      t1 = SBOX[rotated[1]];
      t2 = SBOX[rotated[2]];
      t3 = SBOX[rotated[3]];
    } else if (nk > 6 && i % nk === 4) {
      // AES-256 applies an extra SubWord in the middle of each key block.
      t0 = SBOX[t0];
      t1 = SBOX[t1];
      t2 = SBOX[t2];
      t3 = SBOX[t3];
    }

    const q = (i - nk) * 4;
    const o = i * 4;
    words[o] = words[q] ^ t0;
    words[o + 1] = words[q + 1] ^ t1;
    words[o + 2] = words[q + 2] ^ t2;
    words[o + 3] = words[q + 3] ^ t3;
  }

  return { roundKeys: words, rounds };
}

