/**
 * The AES block cipher itself: a single 16-byte block in, a single 16-byte
 * block out. Modes of operation live in `../modes/`.
 */

import { INV_SBOX, MUL11, MUL13, MUL14, MUL2, MUL3, MUL9, SBOX } from './tables.mjs';
import { VALID_KEY_SIZES, expandKey } from './keySchedule.mjs';
import { PyValueError } from '../python/errors.mjs';

/** Bytes per AES block. Fixed at 128 bits for every key length. */
export const BLOCK_SIZE = 16;

/**
 * The state is a flat 16-byte array; byte `i` sits at row `i % 4`, column
 * `i >> 2` of the FIPS-197 state matrix. ShiftRows therefore walks the array
 * with a stride of 4, and MixColumns works on consecutive groups of 4.
 */
function shiftRows(state, out) {
  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 4; col++) {
      out[col * 4 + row] = state[(((col + row) & 3) * 4) + row];
    }
  }
}

function invShiftRows(state, out) {
  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 4; col++) {
      out[(((col + row) & 3) * 4) + row] = state[col * 4 + row];
    }
  }
}

function mixColumns(state) {
  for (let c = 0; c < 16; c += 4) {
    const a0 = state[c];
    const a1 = state[c + 1];
    const a2 = state[c + 2];
    const a3 = state[c + 3];

    state[c] = MUL2[a0] ^ MUL3[a1] ^ a2 ^ a3;
    state[c + 1] = a0 ^ MUL2[a1] ^ MUL3[a2] ^ a3;
    state[c + 2] = a0 ^ a1 ^ MUL2[a2] ^ MUL3[a3];
    state[c + 3] = MUL3[a0] ^ a1 ^ a2 ^ MUL2[a3];
  }
}

function invMixColumns(state) {
  for (let c = 0; c < 16; c += 4) {
    const a0 = state[c];
    const a1 = state[c + 1];
    const a2 = state[c + 2];
    const a3 = state[c + 3];

    state[c] = MUL14[a0] ^ MUL11[a1] ^ MUL13[a2] ^ MUL9[a3];
    state[c + 1] = MUL9[a0] ^ MUL14[a1] ^ MUL11[a2] ^ MUL13[a3];
    state[c + 2] = MUL13[a0] ^ MUL9[a1] ^ MUL14[a2] ^ MUL11[a3];
    state[c + 3] = MUL11[a0] ^ MUL13[a1] ^ MUL9[a2] ^ MUL14[a3];
  }
}

function addRoundKey(state, roundKeys, round) {
  const offset = round * BLOCK_SIZE;
  for (let i = 0; i < BLOCK_SIZE; i++) state[i] ^= roundKeys[offset + i];
}

/**
 * Raw AES, mirroring the interface of `pyaes.AES`.
 *
 * Construction validates the key length the same way the reference does, so an
 * unusable key is rejected before any block is processed.
 */
export class AES {
  /**
   * @param {Uint8Array} key 16, 24 or 32 raw key bytes
   */
  constructor(key) {
    if (!VALID_KEY_SIZES.includes(key.length)) {
      throw new PyValueError('Invalid key size', [
        ['pyaes/aes.py', 304, '__init__'],
        ['pyaes/aes.py', 134, '__init__'],
      ]);
    }

    const { roundKeys, rounds } = expandKey(key);
    this.roundKeys = roundKeys;
    this.rounds = rounds;
    this.keySize = key.length;

    // Scratch buffers, reused across calls to keep per-block work allocation free.
    this._state = new Uint8Array(BLOCK_SIZE);
    this._scratch = new Uint8Array(BLOCK_SIZE);
  }

  /**
   * Encrypt exactly one block.
   *
   * @param {Uint8Array} plaintext 16 bytes
   * @returns {Uint8Array} 16 fresh bytes of ciphertext
   */
  encrypt(plaintext) {
    const state = this._state;
    const scratch = this._scratch;

    state.set(plaintext);
    addRoundKey(state, this.roundKeys, 0);

    for (let round = 1; round < this.rounds; round++) {
      for (let i = 0; i < BLOCK_SIZE; i++) state[i] = SBOX[state[i]];
      shiftRows(state, scratch);
      state.set(scratch);
      mixColumns(state);
      addRoundKey(state, this.roundKeys, round);
    }

    for (let i = 0; i < BLOCK_SIZE; i++) state[i] = SBOX[state[i]];
    shiftRows(state, scratch);
    state.set(scratch);
    addRoundKey(state, this.roundKeys, this.rounds);

    return new Uint8Array(state);
  }

  /**
   * Decrypt exactly one block.
   *
   * @param {Uint8Array} ciphertext 16 bytes
   * @returns {Uint8Array} 16 fresh bytes of plaintext
   */
  decrypt(ciphertext) {
    const state = this._state;
    const scratch = this._scratch;

    state.set(ciphertext);
    addRoundKey(state, this.roundKeys, this.rounds);

    for (let round = this.rounds - 1; round >= 1; round--) {
      invShiftRows(state, scratch);
      state.set(scratch);
      for (let i = 0; i < BLOCK_SIZE; i++) state[i] = INV_SBOX[state[i]];
      addRoundKey(state, this.roundKeys, round);
      invMixColumns(state);
    }

    invShiftRows(state, scratch);
    state.set(scratch);
    for (let i = 0; i < BLOCK_SIZE; i++) state[i] = INV_SBOX[state[i]];
    addRoundKey(state, this.roundKeys, 0);

    return new Uint8Array(state);
  }
}

