/**
 * Python-shaped exceptions and the fatal-error reporting the frozen
 * (PyInstaller) build emits on an unhandled exception.
 */

/**
 * A `ValueError` raised somewhere below the script's own frames.
 *
 * Each entry of `frames` is `[filename, lineNumber, functionName]`, ordered
 * outermost-first, exactly as CPython prints them.
 */
export class PyValueError extends Error {
  /**
   * @param {string} message the text after `ValueError: `
   * @param {Array<[string, number, string]>} frames library frames to attribute
   *   the failure to, below whatever call-site frames the caller prepends
   */
  constructor(message, frames = []) {
    super(message);
    this.name = 'ValueError';
    this.pyType = 'ValueError';
    this.frames = frames;
  }
}

/**
 * Render a CPython traceback.
 *
 * @param {PyValueError} error the exception being reported
 * @param {Array<[string, number, string]>} callerFrames frames from the script
 *   itself, outermost first
 * @returns {string} the full traceback, newline terminated
 */
export function formatTraceback(error, callerFrames = []) {
  const lines = ['Traceback (most recent call last):'];

  for (const [file, line, fn] of [...callerFrames, ...error.frames]) {
    lines.push(`  File "${file}", line ${line}, in ${fn}`);
  }

  lines.push(`${error.pyType ?? 'Exception'}: ${error.message}`);
  return `${lines.join('\n')}\n`;
}

/**
 * Print a traceback plus the PyInstaller bootloader banner and exit with the
 * status an unhandled Python exception produces.
 *
 * @param {PyValueError} error the exception being reported
 * @param {Array<[string, number, string]>} callerFrames script frames
 * @param {string} scriptName the name the bootloader reports, e.g. `test17`
 */
export function reportFatal(error, callerFrames, scriptName) {
  process.stderr.write(formatTraceback(error, callerFrames));
  process.stderr.write(
    `[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`,
  );
  process.exitCode = 1;
}

