/**
 * Python `bytes` semantics that the port depends on: UTF-8 encoding of `str`
 * and the exact `repr()` CPython prints for a bytes object.
 */

const utf8Encoder = new TextEncoder();

/**
 * `str.encode()` with Python's default codec.
 *
 * @param {string} text
 * @returns {Uint8Array}
 */
export function encodeUtf8(text) {
  return utf8Encoder.encode(text);
}

const BACKSLASH = 0x5c;
const SINGLE_QUOTE = 0x27;
const DOUBLE_QUOTE = 0x22;

/** Short escapes CPython prefers over the `\xNN` form. */
const SHORT_ESCAPES = new Map([
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

/**
 * Reproduce `repr(b)` for a bytes object.
 *
 * CPython prefers single quotes, switching to double quotes only when the data
 * contains a single quote but no double quote. Printable ASCII is emitted
 * literally; everything else becomes `\xNN` (lowercase hex) apart from tab,
 * newline and carriage return.
 *
 * @param {Uint8Array} bytes
 * @returns {string} e.g. `b'\\x0c+2\\xbe'`
 */
export function reprBytes(bytes) {
  const hasSingle = bytes.includes(SINGLE_QUOTE);
  const hasDouble = bytes.includes(DOUBLE_QUOTE);
  const quote = hasSingle && !hasDouble ? DOUBLE_QUOTE : SINGLE_QUOTE;
  const quoteChar = String.fromCharCode(quote);

  let out = `b${quoteChar}`;

  for (const byte of bytes) {
    if (byte === quote || byte === BACKSLASH) {
      out += `\\${String.fromCharCode(byte)}`;
    } else if (SHORT_ESCAPES.has(byte)) {
      out += SHORT_ESCAPES.get(byte);
    } else if (byte >= 0x20 && byte < 0x7f) {
      out += String.fromCharCode(byte);
    } else {
      out += `\\x${byte.toString(16).padStart(2, '0')}`;
    }
  }

  return out + quoteChar;
}

/**
 * `print(value)` for a bytes object: `str(bytes)` is its `repr()`.
 *
 * @param {Uint8Array} bytes
 */
export function printBytes(bytes) {
  process.stdout.write(`${reprBytes(bytes)}\n`);
}

