/**
 * Text measuring and wrapping helpers matching the pieces of Python's
 * `textwrap` that argparse's help formatter relies on.
 */

/**
 * `textwrap.wrap(text, width)` for the single-paragraph, whitespace-collapsing
 * case argparse uses (it pre-normalises whitespace before wrapping).
 *
 * @param {string} text text to wrap
 * @param {number} width maximum line length
 * @returns {string[]} wrapped lines, without trailing whitespace
 */
export function wrapText(text, width) {
  const words = text.split(/\s+/).filter((word) => word.length > 0);
  if (words.length === 0) return [];

  const lines = [];
  let current = words[0];

  for (const word of words.slice(1)) {
    if (current.length + 1 + word.length <= width) {
      current += ` ${word}`;
    } else {
      lines.push(current);
      current = word;
    }
  }

  lines.push(current);
  return lines;
}

