/**
 * A focused port of Python's `argparse` covering the surface this script uses:
 * long options that store a single string value, `-h/--help`, prefix
 * abbreviation, `--opt=value`, required-argument reporting, and the exact
 * usage/help layout and exit codes CPython produces.
 */

import { helpWidth, padRight, wrapText } from './textwrap.mjs';

/** Matches what argparse considers a negative number rather than an option. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/**
 * How argparse chops a usage string into wrappable pieces: bracketed or
 * parenthesised groups stay together, everything else splits on whitespace.
 */
const USAGE_PART = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

/** argparse's `HelpFormatter` layout constants. */
const INDENT = 2;
const MAX_HELP_POSITION = 24;

/** Thrown instead of exiting so callers can control process teardown. */
export class SystemExit extends Error {
  /**
   * @param {number} code process exit status
   */
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

/** `argparse._get_action_name` for optionals. */
function actionName(action) {
  return action.optionStrings.join('/');
}

/** The metavar shown after an option that takes a value. */
function argsString(action) {
  return action.metavar ?? action.dest.toUpperCase();
}

/** `HelpFormatter._format_action_invocation`. */
function formatInvocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  const args = argsString(action);
  return action.optionStrings.map((option) => `${option} ${args}`).join(', ');
}

/** How an action appears inside the usage line. */
function formatUsagePart(action) {
  const part = action.nargs === 0
    ? action.optionStrings[0]
    : `${action.optionStrings[0]} ${argsString(action)}`;
  return action.required ? part : `[${part}]`;
}

export class ArgumentParser {
  /**
   * @param {{ prog: string, env?: NodeJS.ProcessEnv }} options
   */
  constructor({ prog, env = process.env }) {
    this.prog = prog;
    this.env = env;
    this.actions = [];
    this.optionStringActions = new Map();

    this.addArgument(['-h', '--help'], {
      nargs: 0,
      action: 'help',
      dest: 'help',
      help: 'show this help message and exit',
    });
  }

  /**
   * Register an option.
   *
   * @param {string[]} optionStrings e.g. `['--key']`
   * @param {object} [options] `required`, `help`, `metavar`, `nargs`, `action`, `dest`
   * @returns {object} the created action
   */
  addArgument(optionStrings, options = {}) {
    const dest = options.dest ?? optionStrings[optionStrings.length - 1].replace(/^-+/, '').replace(/-/g, '_');
    const action = {
      optionStrings,
      dest,
      nargs: options.nargs ?? 1,
      action: options.action ?? 'store',
      required: options.required ?? false,
      help: options.help ?? null,
      metavar: options.metavar ?? null,
      default: options.default ?? null,
    };

    this.actions.push(action);
    for (const option of optionStrings) this.optionStringActions.set(option, action);
    return action;
  }

  // ---------------------------------------------------------------- help ---

  /** `HelpFormatter._format_usage`, including the multi-line wrapping rules. */
  formatUsageBlock() {
    const prefix = 'usage: ';
    const textWidth = helpWidth(this.env);
    const parts = this.actions.map(formatUsagePart);
    const usage = [this.prog, ...parts].join(' ');

    if (prefix.length + usage.length <= textWidth) {
      return `${prefix}${usage}\n\n`;
    }

    const optParts = parts.join(' ').match(USAGE_PART) ?? [];

    const getLines = (pieces, indent, linePrefix) => {
      const lines = [];
      let line = [];
      let lineLen = (linePrefix ?? indent).length - 1;

      for (const piece of pieces) {
        if (lineLen + 1 + piece.length > textWidth && line.length > 0) {
          lines.push(indent + line.join(' '));
          line = [];
          lineLen = indent.length - 1;
        }
        line.push(piece);
        lineLen += 1 + piece.length;
      }

      if (line.length > 0) lines.push(indent + line.join(' '));
      if (linePrefix !== undefined) lines[0] = lines[0].slice(indent.length);
      return lines;
    };

    let lines;
    if (prefix.length + this.prog.length <= 0.75 * textWidth) {
      const indent = ' '.repeat(prefix.length + this.prog.length + 1);
      lines = optParts.length > 0
        ? getLines([this.prog, ...optParts], indent, prefix)
        : [this.prog];
    } else {
      const indent = ' '.repeat(prefix.length);
      lines = [this.prog, ...getLines(optParts, indent)];
    }

    return `${prefix}${lines.join('\n')}\n\n`;
  }

  /** `ArgumentParser.format_usage`: the usage block trimmed to one newline. */
  formatUsage() {
    return `${this.formatUsageBlock().replace(/\n+$/, '')}\n`;
  }

  /** `ArgumentParser.format_help`. */
  formatHelp() {
    const width = helpWidth(this.env);
    const invocations = this.actions.map(formatInvocation);
    const actionMaxLength = Math.max(...invocations.map((text) => text.length + INDENT));
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
    const actionWidth = Math.max(helpPosition - INDENT - 2, 1);
    const textWidth = Math.max(width - helpPosition, 11);

    const lines = ['options:'];

    this.actions.forEach((action, index) => {
      const invocation = invocations[index];

      if (action.help === null) {
        lines.push(`${' '.repeat(INDENT)}${invocation}`);
        return;
      }

      const helpLines = wrapText(action.help, textWidth);

      if (invocation.length <= actionWidth) {
        lines.push(`${' '.repeat(INDENT)}${padRight(invocation, actionWidth)}  ${helpLines[0]}`);
      } else {
        lines.push(`${' '.repeat(INDENT)}${invocation}`);
        lines.push(`${' '.repeat(helpPosition)}${helpLines[0]}`);
      }

      for (const extra of helpLines.slice(1)) {
        lines.push(`${' '.repeat(helpPosition)}${extra}`);
      }
    });

    const help = `${this.formatUsageBlock()}${lines.join('\n')}\n`;
    return `${help.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
  }

  // --------------------------------------------------------------- exits ---

  /** `ArgumentParser.exit`. */
  exit(code = 0, message = null) {
    if (message !== null) process.stderr.write(message);
    throw new SystemExit(code);
  }

  /** `ArgumentParser.error`: usage on stderr, then a status-2 exit. */
  error(message) {
    process.stderr.write(this.formatUsage());
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  // -------------------------------------------------------------- parsing ---

  /** `ArgumentParser._get_option_tuples`, restricted to this parser's grammar. */
  _getOptionTuples(argString) {
    const result = [];

    if (argString.startsWith('--')) {
      const eq = argString.indexOf('=');
      const prefix = eq === -1 ? argString : argString.slice(0, eq);
      const explicit = eq === -1 ? null : argString.slice(eq + 1);

      for (const [option, action] of this.optionStringActions) {
        if (option.startsWith(prefix)) result.push([action, option, explicit]);
      }
      return result;
    }

    // Single-dash form: -x, -xvalue or -x=value.
    const shortPrefix = argString.slice(0, 2);
    const shortExplicit = argString.slice(2) === '' ? null : argString.slice(2);

    for (const [option, action] of this.optionStringActions) {
      if (option === shortPrefix) {
        result.push([action, option, shortExplicit]);
      } else if (option.startsWith(argString)) {
        result.push([action, option, null]);
      }
    }

    return result;
  }

  /** `ArgumentParser._parse_optional`. */
  _parseOptional(argString) {
    if (argString === '') return null;
    if (!argString.startsWith('-')) return null;

    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null];
    }

    if (argString.length === 1) return null;

    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const option = argString.slice(0, eq);
      if (this.optionStringActions.has(option)) {
        return [this.optionStringActions.get(option), option, argString.slice(eq + 1)];
      }
    }

    const tuples = this._getOptionTuples(argString);
    if (tuples.length > 1) {
      const matches = tuples.map(([, option]) => option).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (tuples.length === 1) {
      return tuples[0];
    }

    // Looks like a negative number, and no option does — treat as positional.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return [null, argString, null];
  }

  /**
   * `ArgumentParser.parse_args`.
   *
   * @param {string[]} argv arguments after the program name
   * @returns {Record<string, string|null>} the populated namespace
   */
  parseArgs(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.action === 'store') namespace[action.dest] = action.default;
    }

    // Classify every token up front; `--` makes everything after it positional.
    const patterns = [];
    const tuples = new Map();
    let sawSeparator = false;

    argv.forEach((token, index) => {
      if (sawSeparator) {
        patterns.push('A');
        return;
      }
      if (token === '--') {
        patterns.push('-');
        sawSeparator = true;
        return;
      }
      const tuple = this._parseOptional(token);
      if (tuple === null) {
        patterns.push('A');
      } else {
        tuples.set(index, tuple);
        patterns.push('O');
      }
    });

    const seen = new Set();
    const extras = [];
    let i = 0;

    while (i < argv.length) {
      if (patterns[i] === '-') {
        i += 1;
        continue;
      }

      if (patterns[i] !== 'O') {
        extras.push(argv[i]);
        i += 1;
        continue;
      }

      const [action, , explicitArg] = tuples.get(i);

      if (action === null) {
        extras.push(argv[i]);
        i += 1;
        continue;
      }

      if (action.action === 'help') {
        if (explicitArg !== null) {
          this.error(`argument ${actionName(action)}: ignored explicit argument '${explicitArg}'`);
        }
        process.stdout.write(this.formatHelp());
        this.exit(0);
      }

      seen.add(action);

      if (explicitArg !== null) {
        namespace[action.dest] = explicitArg;
        i += 1;
      } else if (patterns[i + 1] === 'A') {
        namespace[action.dest] = argv[i + 1];
        i += 2;
      } else {
        this.error(`argument ${actionName(action)}: expected one argument`);
      }
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map(actionName);

    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

