/**
 * Cipher-Block Chaining, mirroring `pyaes.AESModeOfOperationCBC`.
 */

import { AES, BLOCK_SIZE } from '../aes/block.mjs';
import { PyValueError } from '../python/errors.mjs';

/**
 * CBC keeps the previous ciphertext block as state, so successive `encrypt`
 * calls chain together the way the reference implementation's do — the caller
 * feeds one block at a time and the object remembers where it left off.
 */
export class AESModeOfOperationCBC {
  /** Mode identifier, as exposed by the reference implementation. */
  static name = 'CBC';

  /**
   * @param {Uint8Array} key 16, 24 or 32 raw key bytes
   * @param {Uint8Array} [iv] 16-byte initialisation vector; all-zero if omitted
   */
  constructor(key, iv = null) {
    if (iv === null) {
      this._lastCipherblock = new Uint8Array(BLOCK_SIZE);
    } else if (iv.length !== BLOCK_SIZE) {
      throw new PyValueError('initialization vector must be 16 bytes', [
        ['pyaes/aes.py', 381, '__init__'],
      ]);
    } else {
      this._lastCipherblock = Uint8Array.from(iv);
    }

    try {
      this._aes = new AES(key);
    } catch (error) {
      if (error instanceof PyValueError) {
        // Attribute the failure to the constructor call inside CBC's __init__.
        error.frames = [['pyaes/aes.py', 385, '__init__'], ...error.frames];
      }
      throw error;
    }
  }

  /**
   * Encrypt one block, chaining it with the previous one.
   *
   * @param {Uint8Array} plaintext exactly 16 bytes
   * @returns {Uint8Array} the ciphertext block
   */
  encrypt(plaintext) {
    if (plaintext.length !== BLOCK_SIZE) {
      throw new PyValueError('plaintext block must be 16 bytes', [
        ['pyaes/aes.py', 389, 'encrypt'],
      ]);
    }

    const precipherblock = new Uint8Array(BLOCK_SIZE);
    for (let i = 0; i < BLOCK_SIZE; i++) {
      precipherblock[i] = plaintext[i] ^ this._lastCipherblock[i];
    }

    this._lastCipherblock = this._aes.encrypt(precipherblock);
    return Uint8Array.from(this._lastCipherblock);
  }

  /**
   * Decrypt one block, chaining it with the previous one.
   *
   * @param {Uint8Array} ciphertext exactly 16 bytes
   * @returns {Uint8Array} the plaintext block
   */
  decrypt(ciphertext) {
    if (ciphertext.length !== BLOCK_SIZE) {
      throw new PyValueError('ciphertext block must be 16 bytes', [
        ['pyaes/aes.py', 399, 'decrypt'],
      ]);
    }

    const plaintext = this._aes.decrypt(ciphertext);
    for (let i = 0; i < BLOCK_SIZE; i++) plaintext[i] ^= this._lastCipherblock[i];

    this._lastCipherblock = Uint8Array.from(ciphertext);
    return plaintext;
  }
}

