/**
 * Port of test17.py — encrypt a multi-block payload with AES-CBC, printing each
 * ciphertext block as Python's `repr()` of a bytes object.
 *
 * Usage: node test17.mjs --key KEY --iv IV --data DATA
 */

import * as pyaes from './lib/pyaes.mjs';
import { ArgumentParser, SystemExit } from './lib/python/argparse.mjs';
import { encodeUtf8, printBytes } from './lib/python/bytes.mjs';
import { PyValueError, reportFatal } from './lib/python/errors.mjs';

/** Frames the script itself contributes to a traceback, outermost first. */
const MODULE_FRAME = ['test17.py', 27, '<module>'];
const CIPHER_INIT_FRAME = ['test17.py', 12, 'main'];
const ENCRYPT_FRAME = ['test17.py', 19, 'main'];

function main() {
  const parser = new ArgumentParser({ prog: 'test17_executable' });
  parser.addArgument(['--key'], { required: true }); // 16 bytes key
  parser.addArgument(['--iv'], { required: true }); // 16 bytes IV
  parser.addArgument(['--data'], { required: true }); // 48 bytes data (3 blocks)
  const args = parser.parseArgs(process.argv.slice(2));

  // Encrypt multiple blocks with CBC
  let aes;
  try {
    aes = new pyaes.AESModeOfOperationCBC(encodeUtf8(args.key), encodeUtf8(args.iv)); // Initialize AES CBC cipher
  } catch (error) {
    if (error instanceof PyValueError) {
      reportFatal(error, [MODULE_FRAME, CIPHER_INIT_FRAME], 'test17');
      return;
    }
    throw error;
  }

  const data = encodeUtf8(args.data);

  // Encrypt 3 blocks with CBC chaining
  const ciphertexts = [];
  for (let i = 0; i < data.length; i += 16) {
    const block = data.subarray(i, i + 16);
    let cipher;
    try {
      cipher = aes.encrypt(block); // Encrypt each block with CBC chaining
    } catch (error) {
      if (error instanceof PyValueError) {
        reportFatal(error, [MODULE_FRAME, ENCRYPT_FRAME], 'test17');
        return;
      }
      throw error;
    }
    ciphertexts.push(cipher);
  }

  // Print all ciphertexts
  for (const cipher of ciphertexts) {
    printBytes(cipher);
  }
}

try {
  main();
} catch (error) {
  if (error instanceof SystemExit) {
    process.exitCode = error.code;
  } else {
    throw error;
  }
}

